import React, { useState, useEffect, useCallback } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import styled from "styled-components";

const EmployeePage = () => {
  const { id } = useParams();
  const [employeeRole, setEmployeeRole] = useState("driver");
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [selectedEmployeeDetails, setSelectedEmployeeDetails] = useState(null);

  const fetchEmployeesByRole = useCallback(
    async (role) => {
      try {
        const response = await axios.get(
          `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
        );
        setFilteredEmployees(response.data);
      } catch (error) {
        console.error("Error fetching employees:", error);
      }
    },
    [id]
  );

  const fetchEmployeeDetails = async (phone) => {
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employee/${phone}`
      );
      setSelectedEmployeeDetails(response.data);
    } catch (error) {
      console.error("Error fetching employee details:", error);
    }
  };

  useEffect(() => {
    fetchEmployeesByRole(employeeRole);
  }, [employeeRole, fetchEmployeesByRole]);

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <Button onClick={() => alert("Open Add Employee Form")}>
        Add Employee
      </Button>

      <RoleTabs>
        {["driver", "driller", "manager", "worker"].map((role) => (
          <Tab
            key={role}
            onClick={() => setEmployeeRole(role)}
            active={employeeRole === role}
          >
            {role.charAt(0).toUpperCase() + role.slice(1)}
          </Tab>
        ))}
      </RoleTabs>

      <EmployeeList>
        {filteredEmployees.map((employee) => (
          <EmployeeItem key={employee.phone}>
            <div onClick={() => fetchEmployeeDetails(employee.phone)}>
              <strong>{employee.name}</strong> ({employee.phone})
            </div>
            <Button onClick={() => fetchEmployeeDetails(employee.phone)}>
              Details
            </Button>
          </EmployeeItem>
        ))}
      </EmployeeList>

      {selectedEmployeeDetails && (
        <DetailsTable>
          <thead>
            <tr>
              <th>Name</th>
              <th>Phone</th>
              <th>Start Date</th>
              <th>End Date</th>
              <th>Expense</th>
            </tr>
          </thead>
          <tbody>
            {selectedEmployeeDetails.salaryRecords.map((record, index) => (
              <tr key={index}>
                <td>{selectedEmployeeDetails.name}</td>
                <td>{selectedEmployeeDetails.phone}</td>
                <td>{record.startDate}</td>
                <td>{record.endDate}</td>
                <td>{record.expense}</td>
              </tr>
            ))}
          </tbody>
        </DetailsTable>
      )}
    </Container>
  );
};

export default EmployeePage;

// Styled Components
const Container = styled.div`
  padding: 20px;
`;

const Header = styled.header`
  text-align: center;
`;

const LorryTitle = styled.h1`
  font-size: 2rem;
`;

const Button = styled.button`
  padding: 10px;
  margin: 10px 0;
`;

const RoleTabs = styled.div`
  display: flex;
  justify-content: center;
  margin-top: 20px;
`;

const Tab = styled.div`
  padding: 10px 20px;
  cursor: pointer;
  background-color: ${(props) => (props.active ? "#4caf50" : "#ccc")};
  color: ${(props) => (props.active ? "white" : "black")};
  margin-right: 10px;
  border-radius: 5px;
`;

const EmployeeList = styled.ul`
  list-style: none;
  padding: 0;
`;

const EmployeeItem = styled.li`
  margin: 10px 0;
  display: flex;
  justify-content: space-between;
`;

const DetailsTable = styled.table`
  width: 100%;
  margin-top: 20px;
  border-collapse: collapse;

  th,
  td {
    border: 1px solid #ccc;
    padding: 8px;
  }

  th {
    background-color: #f4f4f4;
  }
`;
